	public LimitAddressSetsStep(VTAddToSessionWizardModel model, PluginTool tool) : base(model, "Select Address Range(s)",
			new HelpLocation("VersionTrackingPlugin", "Select_Address_Ranges_Panel"))
    {

		panel = new LimitAddressSetsPanel(tool);
	}

